3.7 Minimal Transformer in PyTorch


Code
# Minimal self-attention block
import torch
import torch.nn as nn

class SelfAttention(nn.Module):
    def __init__(self, d_model, n_heads):
        super().__init__()
        self.attn = nn.MultiheadAttention(d_model, n_heads, batch_first=True)
        self.norm = nn.LayerNorm(d_model)

    def forward(self, x):
        attn_out, _ = self.attn(x, x, x)
        return self.norm(x + attn_out)

12.4 Tool Use / Function Calling
Function calling is how the model “calls” an external tool. The pattern:

You define tools as JSON schemas describing available functions
The LLM outputs structured JSON describing which function to call and with what arguments
Your code executes the function
The result is injected back into the conversation
The LLM reasons over the result and either calls another tool or produces a final answer



Code
from anthropic import Anthropic

client = Anthropic()

tools = [
    {
        "name": "search_documents",
        "description": "Search the internal knowledge base for relevant documents",
        "input_schema": {
            "type": "object",
            "properties": {
                "query": {"type": "string", "description": "Search query"},
                "max_results": {"type": "integer", "default": 5}
            },
            "required": ["query"]
        }
    }
]

# Agent loop
messages = [{"role": "user", "content": "What is our current refund policy?"}]

while True:
    response = client.messages.create(
        model="claude-sonnet-4-6",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "end_turn":
        print(response.content[0].text)
        break

    # Process tool use
    for block in response.content:
        if block.type == "tool_use":
            # Execute the tool
            result = execute_tool(block.name, block.input)
            messages.append({"role": "assistant", "content": response.content})
            messages.append({"role": "user", "content": [
                {"type": "tool_result", "tool_use_id": block.id, "content": result}
            ]})
